insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'gk_fa_v1'
from (values
('117.102.b.1.A',2,'Which sense do you use to see the colors in a painting?','["sight", "taste", "hearing", "smell"]'::jsonb,0,'Your eyes see color.','original'),
('117.102.b.1.A',2,'Which sense tells you that a clay bowl feels bumpy?','["hearing", "touch", "taste", "smell"]'::jsonb,1,'Your hands feel texture.','original'),
('117.102.b.1.B',2,'A line that goes straight across the page is...','["bumpy", "tiny", "horizontal", "round"]'::jsonb,2,'Horizontal lines go side to side.','original'),
('117.102.b.1.B',2,'A circle, a square, and a triangle are all kinds of...','["smells", "sounds", "songs", "shapes"]'::jsonb,3,'Shapes are an element of art.','original'),
('117.102.b.1.B',3,'When the same pattern of stripes keeps happening again and again, we call it...','["repetition", "balance", "taste", "noise"]'::jsonb,0,'Repetition repeats an element.','original'),
('117.102.b.2.A',2,'Which tool could you use to make a wavy line?','["a shoe", "a crayon", "a cup", "a spoon"]'::jsonb,1,'Crayons make lines.','original'),
('117.102.b.2.A',2,'Red, blue, and yellow are examples of...','["sounds", "lines", "colors", "textures"]'::jsonb,2,'Colors are an element of art.','original'),
('117.102.b.2.B',2,'When you put shapes on paper where they feel right to you, you are arranging them...','["by a machine", "by a rule book", "by accident only", "your own way"]'::jsonb,3,'Arranging intuitively means trusting your eyes.','original'),
('117.102.b.2.C',2,'Which is a way to make art with paint?','["using a brush", "using a fork to eat", "using a clock", "using a pillow"]'::jsonb,0,'Painting uses brushes.','original'),
('117.102.b.2.C',3,'Pressing a carved block with ink onto paper is called...','["baking", "printmaking", "swimming", "gardening"]'::jsonb,1,'Printmaking makes prints.','original'),
('117.102.b.2.C',2,'Building art by joining clay, paper, and boxes is called making a...','["recipe", "play", "sculpture", "song"]'::jsonb,2,'Sculptures are 3-D.','original'),
('117.102.b.3.A',2,'A picture of a dog shows the subject of the artwork. The subject is the...','["paper", "paint tube", "frame", "dog"]'::jsonb,3,'The subject is what the picture is about.','original'),
('117.102.b.3.B',2,'Art can show a picture of your...','["family", "favorite words only", "nothing", "numbers only"]'::jsonb,0,'Artists share experiences.','original'),
('117.102.b.3.B',3,'When a friend draws something different from what you draw, it shows people have...','["the same ideas", "different ideas", "no ideas", "no friends"]'::jsonb,1,'People think differently.','original'),
('117.102.b.3.C',2,'Which everyday item was designed by an artist?','["a cloud", "a rock", "a poster", "a leaf"]'::jsonb,2,'Posters are designed.','original'),
('117.102.b.3.C',2,'We use art every day when we see...','["only bugs", "only thunder", "only dirt", "pictures on books and signs"]'::jsonb,3,'Art is all around us.','original'),
('117.102.b.3.D',3,'Counting the petals in a flower drawing connects art to...','["math", "baking", "sleeping", "swimming"]'::jsonb,0,'Counting links art and math.','original'),
('117.102.b.4.A',2,'When you tell someone what you made in your drawing, you are sharing your...','["backpack", "ideas", "lunch", "shoes"]'::jsonb,1,'Artists explain their work.','original'),
('117.102.b.4.B',3,'A place where many artworks are shown for people to see is a...','["garage", "bakery", "museum", "bus"]'::jsonb,2,'Museums display art.','original'),
('117.102.b.4.C',3,'A folder that keeps your pictures together is called a...','["puzzle", "playground", "pillow", "portfolio"]'::jsonb,3,'A portfolio collects artwork.','original'),
('117.103.b.1.A',2,'Which voice do you use when you sing a song?','["singing voice", "calling voice", "inner voice", "whispering voice"]'::jsonb,0,'Singing voice makes music.','original'),
('117.103.b.1.A',2,'The voice you use to talk to a friend is your...','["whispering voice", "speaking voice", "singing voice", "calling voice"]'::jsonb,1,'Speaking voice is for talking.','original'),
('117.103.b.1.A',3,'The voice you use to call your friend across the playground is your...','["inner voice", "speaking voice", "calling voice", "whispering voice"]'::jsonb,2,'A calling voice carries far.','original'),
('117.103.b.1.A',3,'The quiet voice you use in your head when you think is your...','["singing voice", "speaking voice", "calling voice", "inner voice"]'::jsonb,3,'Inner voice is silent.','original'),
('117.103.b.1.B',2,'A child''s singing voice usually sounds...','["higher than a grown man''s voice", "like a trumpet", "silent", "lower than a drum"]'::jsonb,0,'Children sing higher.','original'),
('117.103.b.1.C',2,'Which group of instruments includes drums and rattles?','["brass", "percussion", "woodwinds", "strings"]'::jsonb,1,'Percussion instruments are struck or shaken.','original'),
('117.103.b.1.C',3,'Violins and cellos belong to the...','["percussion family", "woodwind family", "string family", "brass family"]'::jsonb,2,'Strings are plucked or bowed.','original'),
('117.103.b.1.D',2,'Two sounds where one is high and one is low are...','["the same", "silent", "quiet", "different"]'::jsonb,3,'High and low are different.','original'),
('117.103.b.1.D',2,'A song where the singers use more and more volume is getting...','["louder", "slower", "softer", "shorter"]'::jsonb,0,'Louder means more volume.','original'),
('117.103.b.1.D',2,'When the players speed up, the tempo of the music is...','["silent", "fast", "soft", "slow"]'::jsonb,1,'Faster means quick.','original'),
('117.103.b.1.E',2,'The steady pulse you feel in music is the...','["color", "story", "beat", "shape"]'::jsonb,2,'The beat is steady.','original'),
('117.103.b.1.E',3,'Clapping the words of a song is clapping the...','["story", "color", "shape", "rhythm"]'::jsonb,3,'Rhythm follows the words.','original'),
('117.103.b.2.A',2,'Playing a rhythm stick or drum with the class is playing a classroom...','["instrument", "shoe", "toy only", "vegetable"]'::jsonb,0,'Classroom instruments are played together.','original'),
('117.103.b.2.B',3,'Learning songs from different countries helps you hear music from different...','["shapes", "cultures", "weathers", "colors"]'::jsonb,1,'Music reflects cultures.','original'),
('117.103.b.2.C',2,'Marching to the beat is a way to...','["read", "sleep", "move to music", "paint"]'::jsonb,2,'Moving shows the beat.','original'),
('117.103.b.2.C',3,'Walking and hopping are movements that travel across the floor. They are called...','["silent movements", "non-locomotor movements", "sit-down movements", "locomotor movements"]'::jsonb,3,'Locomotor means moving from place to place.','original'),
('117.103.b.2.C',3,'Swaying while staying in one place is a...','["non-locomotor movement", "march", "locomotor movement", "run"]'::jsonb,0,'Non-locomotor stays in place.','original'),
('117.103.b.2.D',3,'Tapping the steady beat on your knees while others clap a different rhythm is...','["a nap", "partwork", "a picture", "a mistake"]'::jsonb,1,'Partwork is different parts at once.','original'),
('117.103.b.2.E',2,'To sing softly, you use a...','["whistle", "loud voice", "quiet voice", "shout"]'::jsonb,2,'Soft means quiet.','original'),
('117.103.b.2.E',2,'To make the music faster, you...','["stop", "sleep", "play slower", "play quicker"]'::jsonb,3,'Quicker is faster.','original'),
('117.103.b.3.A',2,'A rhyme that you chant with a game is a type of...','["musical game", "bike", "recipe", "map"]'::jsonb,0,'Rhymes can be musical.','original'),
('117.103.b.3.A',3,'A song sung only during a holiday season is a...','["math problem", "seasonal song", "science lab", "storybook"]'::jsonb,1,'Seasonal songs match a time of year.','original'),
('117.103.b.3.B',3,'A song about counting from one to ten connects music with...','["swimming", "sleeping", "math", "painting only"]'::jsonb,2,'Counting songs link math.','original'),
('117.103.b.4.A',2,'At a concert, a good audience member...','["runs around", "shouts", "talks loudly", "listens quietly and claps at the end"]'::jsonb,3,'Audiences listen politely.','original'),
('117.103.b.4.B',2,'When you pat your knees in time with the music, you are keeping a steady...','["beat", "story", "color", "picture"]'::jsonb,0,'Beat is steady.','original'),
('117.103.b.4.C',3,'When two songs have an identical steady pulse, their beat is the...','["different", "same", "lost", "silent"]'::jsonb,1,'Same beat means same pulse.','original'),
('117.104.b.1.A',2,'Pretending to be a doctor at play helps you learn about...','["only art", "nothing", "yourself and others", "only math"]'::jsonb,2,'Dramatic play builds self-awareness.','original'),
('117.104.b.1.B',2,'Walking like a big elephant uses expressive...','["spelling", "painting", "counting", "movement"]'::jsonb,3,'Movement shows ideas.','original'),
('117.104.b.1.C',2,'Meowing like a cat is copying a...','["sound", "number", "color", "picture"]'::jsonb,0,'Imitate means copy.','original'),
('117.104.b.1.D',3,'Pretending your hands are a bird flying is imitating an...','["alphabet", "object or animal", "number", "crayon"]'::jsonb,1,'Imitating recreates things.','original'),
('117.104.b.2.A',2,'Using your voice safely in a play means not...','["using a calm voice", "taking turns", "screaming too long", "speaking clearly"]'::jsonb,2,'Safe use protects your voice.','original'),
('117.104.b.2.B',2,'When you play the role of a fireman in a pretend game, you are...','["painting", "reading a book", "cooking", "acting like someone else"]'::jsonb,3,'Roles are pretend characters.','original'),
('117.104.b.2.C',3,'Dramatic play uses pretend, imagination, and...','["acting", "spelling quizzes", "nap time", "math tests"]'::jsonb,0,'Dramatic play is pretending.','original'),
('117.104.b.2.D',2,'Joining your class in a pretend kitchen is taking part in...','["a test", "dramatic play", "a race", "a spelling bee"]'::jsonb,1,'Dramatic play involves pretending.','original'),
('117.104.b.3.A',2,'You can make a stage for your play using...','["a bridge", "only airplanes", "tables and chairs", "only boats"]'::jsonb,2,'Classroom objects can build a stage.','original'),
('117.104.b.3.B',3,'A simple costume can be made from...','["nothing", "glass only", "metal only", "paper, cardboard, or cloth"]'::jsonb,3,'Simple materials work.','original'),
('117.104.b.3.C',3,'Practicing a play before showing it is called...','["rehearsing", "sleeping", "losing", "forgetting"]'::jsonb,0,'Rehearse means practice.','original'),
('117.104.b.3.D',2,'When classmates work together to put on a play, they...','["compete", "cooperate", "argue", "leave"]'::jsonb,1,'Cooperation helps everyone.','original'),
('117.104.b.4.A',3,'Acting out a story about your own family''s traditions shows your...','["lunch", "shoes", "culture", "weather"]'::jsonb,2,'Plays can share family cultures.','original'),
('117.104.b.4.B',3,'Acting out the story of the first Thanksgiving is a story from...','["a cooking show", "a space trip", "a sports game", "American history"]'::jsonb,3,'It shows stories of the past.','original'),
('117.104.b.5.A',2,'Good audience behavior at a play is to...','["watch quietly and clap at the end", "walk around", "use your phone loudly", "shout out"]'::jsonb,0,'Audiences should be respectful.','original'),
('117.104.b.5.B',3,'After a play, you can talk about...','["nothing", "what you saw and how it made you feel", "only the weather", "only what you ate"]'::jsonb,1,'Discussing builds understanding.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
